using System.Text;
using MagicExtract.Projections;
using Mutagen.Bethesda.Skyrim;

namespace MagicExtract;

public static class Reports
{
    private const string Header =
        "<!-- GENERATED by arch-docs/magic/tools/MagicExtract — do not hand-edit. Re-run Run-MagicExtract.ps1. -->\n";

    // ---- spells.csv — the flat balance sheet ------------------------------------------------

    public static void SpellsCsv(string path, Dataset<SpellDto> spells)
    {
        var sb = new StringBuilder();
        sb.AppendLine("Form Key,Editor Id,Name,School,Type,Cast Type,Target Type,Base Cost," +
                      "Computed Auto Cost,Charge Time,Arcane Fever,Winner Overwrite,Taught By");
        // Player-obtainable spells only: a winning Book must teach it. This drops NPC-cast copies,
        // trap projectiles, voice/shout spells and unused leftovers that share a display name with
        // the player spell ("Fireball" exists 30+ times as distinct records). The full set stays
        // in spells.json; script/quest-granted spells have no teaching book and are dropped too.
        // A ">" name prefix is EGO's marker for spells it removed from the game (all also cost
        // 999); their books survive as records but are not distributed, so drop those as well.
        // Grouped by school then type for spreadsheet work; schoolless spells sort last.
        // Name/FormKey tiebreakers keep the row order deterministic so re-runs diff cleanly.
        var ordered = spells.Winners
            .Where(s => s.TaughtBy is { Count: > 0 } && s.Name?.StartsWith('>') != true)
            .OrderBy(s => string.IsNullOrEmpty(s.School?.DisplayName) ? 1 : 0)
            .ThenBy(s => s.School?.DisplayName, StringComparer.Ordinal)
            .ThenBy(s => s.Type, StringComparer.Ordinal)
            .ThenBy(s => s.Name, StringComparer.Ordinal)
            .ThenBy(s => s.FormKey, StringComparer.Ordinal);
        foreach (var s in ordered)
        {
            sb.AppendLine(string.Join(",",
                Csv(s.FormKey), Csv(s.EditorId), Csv(s.Name), Csv(s.School?.DisplayName), Csv(s.Type),
                Csv(s.CastType), Csv(s.TargetType), s.Cost?.BaseCost.ToString() ?? "",
                s.Cost?.ComputedAutoCost?.ToString() ?? "",
                s.ChargeTime.ToString(System.Globalization.CultureInfo.InvariantCulture),
                ArcaneFever(s.Effects),
                Csv(s.Provenance!.Winner),
                Csv(string.Join("; ", s.TaughtBy!.Select(b => b.EditorId ?? b.FormKey)))));
        }
        File.WriteAllText(path, sb.ToString(), new UTF8Encoding(false));
    }

    // ---- scrolls.csv — all 36 winners; scrolls are loot/vendor items, no teach-book filter ----

    public static void ScrollsCsv(string path, Dataset<ScrollDto> scrolls)
    {
        var sb = new StringBuilder();
        sb.AppendLine("Form Key,Editor Id,Name,Cast Type,Target Type,Base Cost,Computed Auto Cost," +
                      "Charge Time,Arcane Fever,Value,Weight,Winner Overwrite");
        var ordered = scrolls.Winners
            .OrderBy(s => s.Name, StringComparer.Ordinal)
            .ThenBy(s => s.FormKey, StringComparer.Ordinal);
        foreach (var s in ordered)
        {
            // CK cast type 3 = "Scroll"; Mutagen's CastType enum has no member for it, so the
            // raw value leaks through ToString(). scrolls.json keeps the raw "3" (it must match
            // Spriggit's identical encoding for verify_against_yaml.py); the sheet reads better.
            sb.AppendLine(string.Join(",",
                Csv(s.FormKey), Csv(s.EditorId), Csv(s.Name),
                Csv(s.CastType == "3" ? "Scroll" : s.CastType), Csv(s.TargetType),
                s.Cost?.BaseCost.ToString() ?? "", s.Cost?.ComputedAutoCost?.ToString() ?? "",
                s.ChargeTime.ToString(System.Globalization.CultureInfo.InvariantCulture),
                ArcaneFever(s.Effects),
                s.Value.ToString(),
                s.Weight.ToString(System.Globalization.CultureInfo.InvariantCulture),
                Csv(s.Provenance!.Winner)));
        }
        File.WriteAllText(path, sb.ToString(), new UTF8Encoding(false));
    }

    // ---- enchantments.csv — all winners, grouped by enchant type ------------------------------

    public static void EnchantmentsCsv(string path, Dataset<EnchantmentDto> enchantments)
    {
        var sb = new StringBuilder();
        sb.AppendLine("Form Key,Editor Id,Name,Enchant Type,Cast Type,Target Type,Enchantment Cost," +
                      "Enchantment Amount,Charge Time,Arcane Fever,Winner Overwrite");
        var ordered = enchantments.Winners
            .OrderBy(e => e.EnchantType, StringComparer.Ordinal)
            .ThenBy(e => e.Name, StringComparer.Ordinal)
            .ThenBy(e => e.FormKey, StringComparer.Ordinal);
        foreach (var e in ordered)
        {
            sb.AppendLine(string.Join(",",
                Csv(e.FormKey), Csv(e.EditorId), Csv(e.Name), Csv(e.EnchantType), Csv(e.CastType),
                Csv(e.TargetType), e.EnchantmentCost.ToString(), e.EnchantmentAmount.ToString(),
                e.ChargeTime.ToString(System.Globalization.CultureInfo.InvariantCulture),
                ArcaneFever(e.Effects),
                Csv(e.Provenance!.Winner)));
        }
        File.WriteAllText(path, sb.ToString(), new UTF8Encoding(false));
    }

    private static string Csv(string? v)
    {
        if (string.IsNullOrEmpty(v)) return "";
        return v.Contains(',') || v.Contains('"') || v.Contains('\n')
            ? "\"" + v.Replace("\"", "\"\"") + "\"" : v;
    }

    /// <summary>Base (no-perk) Arcane Fever a cast inflicts, read off the record's own fever
    /// effect items. Enderal applies fever via _00E_IncreaseArcaneFever* / the Boon spells'
    /// _00E_WohltatArkanistenfieber MGEFs; EGO adds HIDDEN perk-gated variants of each at
    /// reduced magnitude, mutually exclusive by HasPerk conditions — so the no-perk value is
    /// the MAX magnitude among fever effects, never the sum. Reduce effects (Ambrosia) and the
    /// fever-consequence effects (AbDamageHealthConstantFever*) deliberately do not match.
    /// Empty = the record raises no fever.</summary>
    private static string ArcaneFever(IEnumerable<EffectDto>? effects)
    {
        float max = 0; bool any = false;
        foreach (var e in effects ?? [])
        {
            var id = e.BaseEffect?.EditorId ?? "";
            if (!id.Contains("IncreaseArcaneFever") && !id.Contains("WohltatArkanistenfieber")) continue;
            any = true;
            if (e.Magnitude > max) max = e.Magnitude;
        }
        return any ? max.ToString(System.Globalization.CultureInfo.InvariantCulture) : "";
    }

    // ---- magic-overview.md --------------------------------------------------------------------

    public static void Overview(string path, ModlistLoadOrder lo,
        Dataset<SpellDto> spel, Dataset<MagicEffectDto> mgef, Dataset<EnchantmentDto> ench,
        Dataset<ScrollDto> scrl, Dataset<IngestibleDto> alch, Dataset<ShoutDto> shou,
        Dataset<LeveledSpellDto> lvsp, Dataset<GameSettingDto> gmst,
        IReadOnlyDictionary<ActorValue, string> schoolNames, bool costModelOk,
        int? beesLogCount, DateTime? beesLogTime)
    {
        var sb = new StringBuilder(Header);
        sb.AppendLine("# Zenderal magic — overview\n");
        sb.AppendLine("Load-order-winning values for every magic record in the installed Zenderal modlist. " +
                      "Data lives in [`data/`](data/); per-record conflicts in " +
                      "[`magic-conflicts.md`](magic-conflicts.md).\n");

        // BEES
        int needy = lo.Included.Count(e => e.NeedsBees);
        sb.AppendLine("## BEES dependency\n");
        sb.AppendLine($"**{needy} enabled plugins have HEDR 1.71** and load only because " +
                      "*Backported Extended ESL Support* is installed. Records whose winner is one of " +
                      "them carry `winnerNeedsBees: true`. Remove BEES and this dataset is wrong for " +
                      "all of them with no error anywhere.\n");
        if (beesLogCount is not null)
            sb.AppendLine($"Runtime corroboration: the BEES log reports **{beesLogCount}** plugins emulated " +
                          $"(log written {beesLogTime:yyyy-MM-dd HH:mm}).\n");

        // counts
        sb.AppendLine("## Datasets\n");
        sb.AppendLine("| Dataset | Winning records | With overrides | New (non-master) |");
        sb.AppendLine("|---|---:|---:|---:|");
        AppendCount(sb, spel); AppendCount(sb, mgef); AppendCount(sb, ench); AppendCount(sb, scrl);
        AppendCount(sb, alch); AppendCount(sb, shou); AppendCount(sb, lvsp); AppendCount(sb, gmst);
        sb.AppendLine();

        // top conflict winners
        sb.AppendLine("## Who wins the conflicts\n");
        sb.AppendLine("Plugins ranked by how many overridden magic records they end up winning:\n");
        var winners = new Dictionary<string, int>();
        foreach (var p in AllProvenance(spel, mgef, ench, scrl, alch, shou, lvsp))
            if (p.Chain.Count > 1)
                winners[p.Winner] = winners.GetValueOrDefault(p.Winner) + 1;
        sb.AppendLine("| Plugin | Conflicted records won |");
        sb.AppendLine("|---|---:|");
        foreach (var (name, count) in winners.OrderByDescending(kv => kv.Value).Take(20))
            sb.AppendLine($"| {name} | {count} |");
        sb.AppendLine();

        // schools
        sb.AppendLine("## Spells by school\n");
        sb.AppendLine("| School (Enderal name) | Actor value | Winning spells |");
        sb.AppendLine("|---|---|---:|");
        var bySchool = spel.Winners.GroupBy(s => s.School?.DisplayName ?? "(none)")
            .OrderByDescending(g => g.Count());
        foreach (var g in bySchool)
        {
            var av = g.First().School?.ActorValue ?? "—";
            sb.AppendLine($"| {g.Key} | {av} | {g.Count()} |");
        }
        sb.AppendLine();

        // cost model
        sb.AppendLine("## Cost model\n");
        sb.AppendLine("```");
        sb.AppendLine("effectCost    = floor( mgef.BaseCost * max(magnitude,1)^1.1 * durFactor^1.1 )");
        sb.AppendLine("durFactor     = 1 for Concentration effects (charged per second)");
        sb.AppendLine("                else (duration==0 ? 10 : duration) / 10");
        sb.AppendLine("spellAutoCost = Σ effectCost   // per-effect floor, then sum");
        sb.AppendLine("```");
        sb.AppendLine(costModelOk
            ? "\nFormula validated this run against base Enderal's own self-consistent spells (≥97% exact;" +
              " the remainder are four known authored-drift records in base Enderal itself)." +
              " `costDrift ≠ 0` on a non-`ManualCostCalc` spell means its stored cost no longer matches its" +
              " live effect data — an override edited a shared MGEF or the spell's durations without a CK" +
              " recompute. Those are rebalancing findings, filter `costDrift` in `data/spells.json`.\n"
            : "\n**DISABLED this run** — formula validation fell below 97%, so `computedAutoCost`/`costDrift` are null.\n");
        sb.AppendLine("Runtime cost past `baseCost` is skill/perk-dependent; see `costModel` in " +
                      "[`data/lookups.json`](data/lookups.json) for the winning GMST curve " +
                      "(approximate — the 1/400 constant is engine-side).\n");

        // caveat
        sb.AppendLine("## What a record dump cannot see\n");
        sb.AppendLine("A lot of Enderal's magic balance lives in **Papyrus**, not records " +
                      "(e.g. `_00E_A1_ArcticWindME` carries `_00E_A1_ArcticWindSC` with a `PlayerLevel` " +
                      "property). Effects with attached scripts carry a `scripts[]` block in " +
                      "`magic-effects.json` — treat those as *flagged for manual reading* in " +
                      "`reference/base/EnderalScripts/source/scripts/`, not fully described here.\n");

        File.WriteAllText(path, sb.ToString(), new UTF8Encoding(false));
    }

    private static void AppendCount<TDto>(StringBuilder sb, Dataset<TDto> ds) where TDto : class, IRecordDto
    {
        int overridden = 0, newRecs = 0;
        foreach (var w in ds.Winners)
        {
            var p = w.Provenance!;
            if (p.Chain.Count > 1) overridden++;
            if (p.IsNewRecord) newRecs++;
        }
        sb.AppendLine($"| `{ds.Name}.json` ({ds.RecordType}) | {ds.Winners.Count} | {overridden} | {newRecs} |");
    }

    private static IEnumerable<ProvenanceDto> AllProvenance(params object[] datasets)
    {
        foreach (var ds in datasets)
        {
            var winners = (System.Collections.IEnumerable)ds.GetType().GetProperty("Winners")!.GetValue(ds)!;
            foreach (var w in winners)
                yield return ((IRecordDto)w).Provenance!;
        }
    }

    // ---- magic-conflicts.md ----------------------------------------------------------------------

    public static void Conflicts(string path, IConflictSource[] sources)
    {
        var sb = new StringBuilder(Header);
        sb.AppendLine("# Zenderal magic — conflict index\n");
        sb.AppendLine("Every magic record more than one plugin touches, with what the winner changed " +
                      "relative to the first carrier in the load order. `∅` = field absent/default on " +
                      "that side; `…` = complex value (see the JSON).\n");
        foreach (var src in sources)
        {
            var rows = src.ConflictRows().ToList();
            if (rows.Count == 0) continue;
            sb.AppendLine($"\n## {src.Name} ({rows.Count})\n");
            sb.AppendLine("| FormKey | EditorID | Name | Winner | Chain | Changes |");
            sb.AppendLine("|---|---|---|---|---|---|");
            foreach (var (fk, eid, name, prov, changes) in rows.OrderBy(r => r.FormKey, StringComparer.Ordinal))
            {
                string chain = string.Join(" → ", prov.Chain.Select(Shorten));
                string bees = prov.WinnerNeedsBees ? " ⚠BEES" : "";
                string ch = changes is null ? "—"
                    : Md(string.Join("; ", changes.Take(8))) + (changes.Count > 8 ? "; …" : "");
                sb.AppendLine($"| `{fk}` | `{eid ?? "—"}` | {Md(name ?? "—")} | {Shorten(prov.Winner)}{bees} | {chain} | {ch} |");
            }
        }
        File.WriteAllText(path, sb.ToString(), new UTF8Encoding(false));
    }

    private static string Shorten(string plugin) => plugin switch
    {
        "Skyrim.esm" => "Skyrim(=Enderal)",
        "Enderal - Forgotten Stories.esm" => "FS",
        "Enderal SE - Gameplay Overhaul.esp" => "EGO",
        _ => plugin.Replace(".esp", "").Replace(".esm", "").Replace(".esl", ""),
    };

    private static string Md(string s) => s.Replace("|", "\\|").Replace("\n", " ");
}
